Definition bp_frontW (lo spa ff fp E : Z) : list (Z * Z) :=
  [(lo, spa + 216); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16); (E, E + 24)]%Z.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma bp_front : forall (Q : machine_state -> Prop) (m1 : mem) (sp : word) (spa lo shi : Z) (LF : list fframe) (LB : list block) (s : as_St H) (m0 : mem)
    (P E p0 n : Z) (c : pcore) (pad7 pad2 ej j216 : list byte) (gap : list cell)
    (ra gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  (* [comment removed for export] *)
  rw_cells asegs m1 spa [CB 216 j216] -> rw_cells asegs m1 (spa + 216) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 216) ->
  (spa = bv_unsigned sp + -320 \/ spa = bv_unsigned sp + -336) -> spa mod 32 = 0 ->
  stk asegs m1 lo spa -> lo + 336 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp <= shi -> mem_inv asegs m1 ->
  tp = Z_to_bv 64 ATP -> ACONST m1 -> athr_cells m1 -> as_RFS H LF m1 -> (length LF < AFS_MAXLIVE)%nat -> stack0 m1 lo shi ->
  (* [comment removed for export] *)
  rw_cells asegs m1 P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> pc_state c <> 11 ->
  as_RHEAP H s LB m0 -> aobj LB LF P 344 -> P mod 8 = 0 -> accessible m1 P 344 ->
  rw_cells asegs m1 E [CB 24 ej] -> aobj LB LF E 24 -> E mod 8 = 0 -> accessible m1 E 24 -> shvis m1 E (E + 24) ->
  (P + 344 <= E \/ E + 24 <= P) ->
  0 <= p0 -> 0 <= n -> p0 + n < 2^64 ->
  (forall (m3 : mem) (ff fp : Z) (rax y0 y1 y2 a0x a1x a2x a3x a4x a5x a6x a7x y3 y4 y5 y6 : word) (j0 j160 jt ja j48 jb j80 jc j112 : list byte),
     munch (bp_frontW lo spa ff fp E) m1 m3 -> wmono asegs m1 m3 -> mem_inv asegs m3 ->
     fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) m3 -> ACONST m3 -> stack0 m3 lo shi ->
     stk asegs m3 lo spa ->
     rw_cells asegs m3 spa (bp_locals E P p0 ff (p0 + n) j0 j160 jt p0) ->
     rw_cells asegs m3 (spa + 216) gap ->
     rw_cells asegs m3 ff (bp_ffr spa fp ja j48 jb j80 jc j112) ->
     rw_cells asegs m3 (sh ff) (bp_sh F8b F8b F8b) ->
     rw_cells asegs m3 fp [C1 (b8 1)] ->
     rw_cells asegs m3 P (ParserCoreCells c pad7 pad2) ->
     rw_cells asegs m3 E (ErrCodeCells EC_clear) ->
     accessible m3 P 344 -> accessible m3 E 24 -> shvis m3 E (E + 24) ->
     evt asegs Q (bp_ms BP_DISP rax spa gp tp y0 y1 y2 sp a0x a1x a2x a3x a4x a5x a6x a7x E P ff n y3 y4 y5 y6 F fc m3)) ->
  evt asegs Q (MS (mkR ra (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (wz P) (wz p0) (wz n) (wz E) a4 a5 a6 a7
                      s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
